ALLOWED = {
  'CREATED': {'PAYMENT_PENDING', 'PLACED', 'FAILED'},
  'PAYMENT_PENDING': {'PLACED', 'FAILED'},
  'PLACED': {'ACCEPTED', 'CANCELLED'},
  'ACCEPTED': {'RIDER_ASSIGNED', 'CANCELLED'},
  'RIDER_ASSIGNED': {'PICKED_UP', 'ACCEPTED', 'CANCELLED'},   # ACCEPTED = unassign
  'PICKED_UP': {'DELIVERED', 'UNDELIVERABLE'},
}
def transition(order_id, expected_version, to, actor, payload):
    with db.tx() as tx:
        o = tx.get(order_id)
        if o.version != expected_version: raise Conflict(o)
        if to not in ALLOWED.get(o.status, ()): raise IllegalTransition(o.status, to)
        n = tx.exec("UPDATE orders SET status=%s, version=version+1 "
                    "WHERE order_id=%s AND version=%s", to, order_id, expected_version)
        if n == 0: raise Conflict(tx.get(order_id))
        tx.insert('order_events', order_id, o.version + 1, o.status, to, actor, payload)
    return o.version + 1

def dispatch_tick(zone):
    orders = open_orders(zone)                      # ACCEPTED, not assigned
    jobs = orders + candidate_pairs(orders, max_extra_delay=8*MIN)
    riders = set()
    for o in orders:
        for cell in h3.k_ring(h3.cell(o.restaurant, res=9), k=3):
            riders |= redis.smembers(f"cell:{cell}")
    riders = [r for r in riders if state(r) == 'IDLE' or finishing_soon(r)]
    cost = {}
    for r in riders:
        for j in jobs:
            t_pick = eta(r.pos, j.pickup)
            wait_food = max(0, j.ready_at - (now + t_pick))
            wait_rider = max(0, (now + t_pick) - j.ready_at)
            cost[r, j] = t_pick + j.drop_time + 0.5*wait_food + 1.0*wait_rider                          - age_bonus(j) + fairness_penalty(r)
    plan = min_cost_assignment(cost, each_order_once=True)
    for r, j in plan:
        send_offer(r, j, expires_in=30*SEC, version=state_version(r))
